INSERT INTO landmarks (name, category, description, latitude, longitude, foundation_year) VALUES('The Main Building (Ivory Tower)','Infrastructure','Construction began in 1938 and the building officially opened in 1941. It is the iconic symbol of Makerere University.',0.3336553999999999909,32.56756049999999903,1941);
INSERT INTO landmarks (name, category, description, latitude, longitude, foundation_year) VALUES('Freedom Square','Infrastructure','It serves as the designated ground for major university ceremonies and every graduation congregation since Makerere''s early days as a technical school in 1922. It was formerly dubbed as ''Freedom Square'' during the political shifts of the 1970s. But beyond academic functions, it is famous historically as the staging ground for Makerere''s intense student politics, guild rallies, general freshers orientation and passionate debates that have shaped the national political landscape of Uganda.',0.3337585000000000134,32.56838369999999828,1922);
INSERT INTO landmarks (name, category, description, latitude, longitude, foundation_year) VALUES('Main Library','Infrastructure','Established in 1949, the Main Library is the oldest academic library in Uganda. It serves as the National Reference Library and legal depository for published works in Uganda. The library houses the renowned Africana Section, which contains rare historical collections, photographs, manuscripts, and diaries of early explorers and political figures.',0.3293574000000000223,32.61616589999999861,1949);
INSERT INTO landmarks (name, category, description, latitude, longitude, foundation_year) VALUES('Senate Building','Infrastructure','Commissioned in 2001, the Senate Building serves as Makerere University''s central hub for academic administration. It houses the Office of the Academic Registrar and supports services such as enrollment, transcript verification, and graduation clearance. Designed as a modern multi-storey facility, it accommodates the University Senate, the institution''s highest academic decision-making body.',0.3326347000000000053,32.56858609999999742,2001);
INSERT INTO landmarks (name, category, description, latitude, longitude, foundation_year) VALUES('Lumumba Hall','Hall','Opened in 1971 to accommodate the post-independence increase in student enrollment, Lumumba Hall was named after Patrice Lumumba, the first Prime Minister of the Democratic Republic of the Congo. Known as ''The Elephants,'' the hall has a strong tradition of student leadership and campus solidarity. It is also home to the iconic ''Gongom'' monument, a symbol of student autonomy and the hall''s cultural heritage.',0.3319012000000000073,32.56608510000000222,1971);
INSERT INTO landmarks (name, category, description, latitude, longitude, foundation_year) VALUES('Mary Stuart Hall','Hall','Officially opened in 1953, Mary Stuart Hall was established as Makerere University''s permanent residence for female students after the university admitted its first women in 1945. Named after Mary Stuart, wife of Anglican Bishop Cyril Stuart, the hall symbolizes the advancement of women''s higher education in East Africa. Known as ''The Box,'' it shares a long-standing cultural alliance with Lumumba Hall through the ''Lumbox'' tradition.',0.3306141000000000218,32.56678509999999704,1953);
INSERT INTO landmarks (name, category, description, latitude, longitude, foundation_year) VALUES('Mitchell Hall','Hall','Originating in the 1930s as one of the original hostels of Makerere Technical School, Mitchell Hall was later named after Sir Philip Mitchell, the colonial Governor of Uganda, who supported Makerere''s development into a center of higher learning. Known as ''The Rats,'' the hall is recognized for its traditions of resilience, independence, and active participation in student leadership and campus activities.',0.3338704000000000116,32.57032650000000018,1930);
INSERT INTO landmarks (name, category, description, latitude, longitude, foundation_year) VALUES('University Hall','Hall','Officially opened in 1957, University Hall is distinguished by its traditional collegiate courtyard design. Known as ''The Goats'' (Mbaazi), the hall represents resilience, determination, and independence. It is also well known for its historic rivalry with Mitchell Hall, particularly during inter-hall sports competitions and student guild campaigns.',0.3331180999999999725,32.57244719999999916,1957);
INSERT INTO landmarks (name, category, description, latitude, longitude, foundation_year) VALUES('Livingstone Hall','Hall','Officially opened in 1959, Livingstone Hall was established to accommodate the growing student population during Makerere University''s affiliation with the University of London. Named after the British explorer and missionary David Livingstone, the hall is known for its tradition of academic excellence and disciplined student life. Its residents, known as ''Stonians'' or ''Gentlemen,'' share a long-standing cultural and political alliance with Africa Hall through the Afro-Stone solidarity.',0.3388683000000000111,32.56799339999999888,1959);
INSERT INTO landmarks (name, category, description, latitude, longitude, foundation_year) VALUES('Africa Hall','Hall','Officially opened in 1971, Africa Hall was named to celebrate the spirit of Pan-African liberation and independence across the African continent. Its residents, known as ''The Crocodiles,'' are recognized for their resilience, intelligence, and strong sense of community. Together with Livingstone Hall, Africa Hall forms the Afro-Stone solidarity, a prominent alliance in Makerere University''s student leadership and guild politics.',0.3380639999999999757,32.56865830000000273,1971);
INSERT INTO landmarks (name, category, description, latitude, longitude, foundation_year) VALUES('Nkrumah Hall','Hall','Officially opened on 6 July 1954 as ''New Hall,'' the residence was later renamed in honour of Osagyefo Dr. Kwame Nkrumah, the first President of Ghana and a leading figure in the Pan-African movement. Known as ''The Rams,'' the hall symbolizes strength, determination, and leadership. A prominent bronze statue of Kwame Nkrumah stands at its entrance, serving as a landmark for cultural events and student gatherings.',0.3359255999999999909,32.56938139999999749,1954);
INSERT INTO landmarks (name, category, description, latitude, longitude, foundation_year) VALUES('Nsibirwa Hall','Hall','Originally opened in 1952 as Northcote Hall, the residence was later renamed Nsibirwa Hall in 1996 to honour Martin Luther Nsibirwa, the former Katikkiro (Prime Minister) of Buganda. The hall is known for its rich student traditions and its unique history of student self-governance. Today, its residents are known as ''Roosters.''',0.3358200000000000073,32.57001209999999958,1952);
INSERT INTO landmarks (name, category, description, latitude, longitude, foundation_year) VALUES('Dag Hammarskjöld Hall','Hall','Established in 1961, Dag Hammarskjöld Hall was named in honour of Dag Hammarskjöld, the second Secretary-General of the United Nations, who died in a plane crash while on a peace mission to the Congo. The hall was dedicated as a quiet residential community for postgraduate Master''s and PhD students, providing an environment that supports advanced study and research.',0.3338979999999999725,32.57235080000000237,1961);
INSERT INTO landmarks (name, category, description, latitude, longitude, foundation_year) VALUES('College of Computing and Information Sciences (CoCIS)','College','Officially established in 2010 as part of Makerere University''s collegiate restructuring, the College of Computing and Information Sciences (CoCIS) was formed through the merger of the Institute of Computer Science, the Faculty of Computing and Information Technology (FCIT), and the East African School of Library and Information Science (EASLIS). Today, it is one of Africa''s leading centres for computing, information technology, and digital innovation, with modern teaching facilities, advanced laboratories, and research infrastructure.',0.3314192000000000248,32.57063579999999803,2010);
INSERT INTO landmarks (name, category, description, latitude, longitude, foundation_year) VALUES('College of Engineering, Design, Art and Technology (CEDAT)','College','Officially established in 2010 through the merger of the Faculty of Technology and the School of Fine Art, CEDAT became one of Makerere University''s leading centres for engineering, architecture, design, and technology. Building on the legacy of the Faculty of Technology, which was founded in 1970, the college provides modern workshops, laboratories, and studios for training engineers, architects, designers, and technology professionals.',0.336112299999999975,32.56452629999999714,2010);
INSERT INTO landmarks (name, category, description, latitude, longitude, foundation_year) VALUES('Margaret Trowell School of Industrial and Fine Arts (MTSIFA)','College','Founded in 1937 by British artist Margaret Trowell, the Margaret Trowell School of Industrial and Fine Arts is the oldest professional art school in East Africa. It began as informal art classes conducted at Trowell''s residence before becoming part of Makerere University in the 1940s. The school is home to the Trowell Gallery, which preserves an important collection of African contemporary art, sculptures, paintings, and ceramics.',0.3287404999999999911,32.56920579999999888,1937);
INSERT INTO landmarks (name, category, description, latitude, longitude, foundation_year) VALUES('School of Law','College','Officially established as an autonomous Faculty of Law in 1968, the School of Law is Uganda''s oldest premier legal training institution. Originally operating as a department within the Faculty of Social Sciences, it has played a significant role in legal education and the development of the country''s legal profession. The school is now housed in a modern neo-classical building equipped with advanced moot courtrooms for practical legal training.',0.3284765000000000045,32.56970799999999855,1968);
INSERT INTO landmarks (name, category, description, latitude, longitude, foundation_year) VALUES('College of Business and Management Sciences (CoBAMS)','College','Officially established in 2010 during Makerere University''s collegiate restructuring, the College of Business and Management Sciences (CoBAMS) brought together the Institute of Economics and the School of Statistics and Planning under one academic college. Today, it is a leading centre for business, economics, management, statistics, and policy research, with facilities that combine historic campus architecture and modern academic buildings.',0.3350244,32.56860350000000181,2010);
INSERT INTO landmarks (name, category, description, latitude, longitude, foundation_year) VALUES('College of Humanities and Social Sciences (CHUSS)','College','Officially established on 5 November 2010 during Makerere University''s collegiate restructuring, the College of Humanities and Social Sciences (CHUSS) was formed through the merger of the Faculties of Arts and Social Sciences. Building on a heritage dating back to the university''s early expansions in the 1930s and 1940s, the college has become a leading centre for the humanities, social sciences, and post-colonial scholarship.',0.3323611000000000204,32.56753919999999881,2010);
INSERT INTO landmarks (name, category, description, latitude, longitude, foundation_year) VALUES('College of Natural Sciences (CoNAS)','College','Officially established in 2010 during Makerere University''s collegiate restructuring, the College of Natural Sciences (CoNAS) brought together the long-established departments of Physics, Chemistry, and Mathematics. Building on a scientific heritage that dates back to the 1950s, the college is a leading centre for scientific research, innovation, and education, supported by modern laboratories and specialized research facilities.',0.3360061999999999772,32.56582490000000263,2010);
INSERT INTO landmarks (name, category, description, latitude, longitude, foundation_year) VALUES('College of Health Sciences (School of Medicine)','College','Tracing its origins to 1924 as the Mulago Medical School, the College of Health Sciences is the oldest medical training institution in East Africa. Developed through a long-standing affiliation with the University of London, it has played a pioneering role in medical education, research, and healthcare in the region. Located on Mulago Hill and closely integrated with Mulago National Referral Hospital, the college continues to train medical professionals while supporting clinical research and patient care.',0.3379660999999999916,32.57575390000000226,1924);
INSERT INTO landmarks (name, category, description, latitude, longitude, foundation_year) VALUES('College of Education and External Studies (CEES)','College','Tracing its origins to the Department of Education established in 1947, the College of Education and External Studies (CEES) has played a central role in training teachers, educational leaders, and researchers in Uganda. Located near Makerere University''s main gate, the college supports teacher education, distance learning, and educational research through modern multimedia studios, learning resource centres, and outreach programmes.',0.3348781000000000118,32.57089669999999871,1947);
INSERT INTO landmarks (name, category, description, latitude, longitude, foundation_year) VALUES('College of Veterinary Medicine, Animal Resources and Bio-security (CoVAB)','College','Tracing its origins to veterinary training in the 1930s, the College of Veterinary Medicine, Animal Resources and Bio-security (CoVAB) builds on the Faculty of Veterinary Medicine established in 1953. Today, the college is a leading centre for veterinary medicine, animal health, agriculture, and bio-security research. Located on the north-western slopes of Makerere University, it is distinguished by its iconic concrete water tower.',0.3399576000000000265,32.56768490000000327,1953);
INSERT INTO landmarks (name, category, description, latitude, longitude, foundation_year) VALUES('St. Francis Chapel','Spiritual','Built in 1942, St. Francis Chapel is Makerere University''s historic Anglican place of worship. Located near the main administrative area, the chapel is renowned for its striking mosaic artwork on the front exterior wall, symbolizing spiritual illumination. It continues to serve as a centre for worship, reflection, and spiritual life within the university community.',0.3329318,32.56745599999999997,1942);
INSERT INTO landmarks (name, category, description, latitude, longitude, foundation_year) VALUES('St. Augustine Catholic Chapel','Spiritual','Consecrated in the 1950s and named after St. Augustine of Hippo, St. Augustine Catholic Chapel serves as the Catholic place of worship at Makerere University. The chapel is distinguished by its mid-century modern ecclesiastical architecture and expansive stained-glass windows, providing a welcoming space for worship, prayer, and spiritual formation.',0.3336281999999999859,32.566748699999998,1950);
INSERT INTO landmarks (name, category, description, latitude, longitude, foundation_year) VALUES('Main Mosque','Spiritual','Established in the 1970s with support from international Islamic partnerships, the Main Mosque serves as Makerere University''s principal Islamic place of worship. Situated on a scenic ridge within the campus, it is distinguished by its classic Islamic architecture, featuring a soaring minaret and a prominent central dome. The mosque continues to serve as a centre for worship, spiritual guidance, and community life.',0.3298732999999999805,32.5711668000000003,1970);
INSERT INTO landmarks (name, category, description, latitude, longitude, foundation_year) VALUES('Makerere Innovation Hub','College','Officially launched in July 2023, the Makerere Innovation Hub was established through a flagship partnership with the United Nations Development Programme (UNDP). Located at the Yusuf Lule Central Teaching Facility, the hub provides an incubation environment for software engineering, robotics, entrepreneurship, and digital innovation, supporting students, researchers, and technology startups.',0.3323261000000000131,32.5704417000000035,2023);
INSERT INTO landmarks (name, category, description, latitude, longitude, foundation_year) VALUES('Makerere University Hospital','Infrastructure','Makerere University Hospital originated as a small student sick bay clinic before expanding after the university acquired the premises of the former Nile Nursing Home following the 1972 Asian expulsion. The sick bay was relocated to the new premises, and on 16th February 1978, during the presidency of Idi Amin Dada, the facility was officially upgraded to full hospital status. It continues to provide healthcare services to the Makerere University community.',0.3279056000000000192,32.57070730000000224,1972);
INSERT INTO landmarks (name, category, description, latitude, longitude, foundation_year) VALUES('The University Printery','Infrastructure','The University Printery was established to help Makerere University become self-reliant in producing academic and institutional literature. The highly secured facility is responsible for publishing internal examination papers, research monographs, graduation booklets, and other official university materials.',0.3336862999999999913,32.56741410000000058,1960);
INSERT INTO landmarks (name, category, description, latitude, longitude, foundation_year) VALUES('Swimming Pool & Sports Grounds','Infrastructure','The Swimming Pool & Sports Grounds complex was constructed during the high-investment post-independence era of the 1960s. It features one of the oldest open-air Olympic-sized swimming pools in Uganda and includes the main sports field known as Impala Grounds, serving as a major recreational and sporting facility for the Makerere University community.',0.3350716999999999723,32.5692295999999999,1960);
INSERT INTO landmarks (name, category, description, latitude, longitude, foundation_year) VALUES('The University Guest House','Infrastructure','The University Guest House was built in the late 1950s, reflecting mid-century colonial architectural design. The low-rise facility provides a quiet green sanctuary for accommodating visiting scholars, researchers, and members of external academic networks away from the busier areas of the campus.',0.3312273000000000022,32.56943470000000218,1950);
INSERT INTO landmarks (name, category, description, latitude, longitude, foundation_year) VALUES('The Main Gate','Gate','The Main Gate of Makerere University was originally constructed in the 1940s as a simple rustic stone-walled colonial gate checkpoint along Makerere Hill Road. After standing for nearly 80 years, it was completely demolished and reconstructed in 2022 into a majestic dual-carriage monument as part of the university''s Centenary celebrations.',0.3292010000000000213,32.57103409999999855,1940);
INSERT INTO landmarks (name, category, description, latitude, longitude, foundation_year) VALUES('The Eastern Gate','Gate','The Eastern Gate was established in the 1940s as a simple transit passage allowing staff and scholars to exit down the slopes of Makerere Hill into the Wandegeya trading center. Over the decades, it developed into a major pedestrian access point and later received modern overhead architectural signage to integrate with the wider campus entrance network.',0.3357750999999999931,32.57259200000000021,1940);
INSERT INTO landmarks (name, category, description, latitude, longitude, foundation_year) VALUES('The Western Gate (Kikoni Gate)','Gate','The Western Gate, also known as Kikoni Gate, serves as a critical daily access point facing the extensive residential hostel district of Kikoni. It provides a major transit route for commuting students and has been the focus of modern architectural redesign initiatives by campus engineering scholars to improve its functionality and appearance.',0.3348122000000000042,32.56391039999999749,1970);
INSERT INTO landmarks (name, category, description, latitude, longitude, foundation_year) VALUES('Central Teaching Facility I (CTF I)','Infrastructure','Commissioned in 2009, Central Teaching Facility I (CTF I) was established to expand Makerere University''s teaching capacity and provide modern learning spaces for its growing student population. The multi-storey facility houses lecture theatres, classrooms, computer laboratories, and administrative offices, serving students from multiple colleges across the university.',0.3324983000000000243,32.56901810000000097,2009);
INSERT INTO landmarks (name, category, description, latitude, longitude, foundation_year) VALUES('Central Teaching Facility II (CTF II)','Infrastructure','Commissioned in 2013, Central Teaching Facility II (CTF II) was constructed to further expand Makerere University''s teaching infrastructure and address increasing student enrolment. Located adjacent to CTF I, the facility provides modern lecture theatres, classrooms, seminar rooms, and learning spaces that support teaching and academic activities across multiple colleges. It also accommodates innovation initiatives, including the Makerere Innovation Hub.',0.3358248999999999818,32.56823980000000062,2013);
INSERT INTO landmarks (name, category, description, latitude, longitude, foundation_year) VALUES('Mastercard Foundation Office','Infrastructure','Established in 2013 as part of the Mastercard Foundation Scholars Program, the Mastercard Foundation Office coordinates scholarship administration, student support services, leadership development, and partnership activities at Makerere University. The office works to expand access to quality higher education for academically talented young people, particularly those from economically disadvantaged backgrounds, while promoting innovation, entrepreneurship, and community engagement.',0.3323265000000000246,32.57085330000000312,2013);
INSERT INTO landmarks (name, category, description, latitude, longitude, foundation_year) VALUES('Makerere Rotaract Club','Infrastructure','Founded in 1991, the Makerere Rotaract Club is one of the university''s leading student service organizations and operates under the global Rotary International network. The club promotes leadership, professional development, community service, and fellowship among students through projects focused on education, health, environmental conservation, and youth empowerment. Over the years, it has become one of the most active student organizations at Makerere University.',NULL,NULL,1991);
INSERT INTO landmarks (name, category, description, latitude, longitude, foundation_year) VALUES('Complex Hall','Hall','Opened in 1990, Complex Hall was established to provide residential accommodation for Makerere University students as enrolment continued to grow. Located near the College of Education and External Studies, the hall offers convenient access to lecture facilities and academic resources. Over the years, it has become an important part of the university''s residential community, providing accommodation while supporting student life and academic engagement.',0.3299601999999999813,32.57011469999999776,1990);
INSERT INTO landmarks (name, category, description, latitude, longitude, foundation_year) VALUES('Galloway House','Hall','Established in 1924 alongside the growth of the Mulago Medical School, Galloway House serves as a residence for students of the Makerere University College of Health Sciences. Located on Mulago Hill near Mulago National Referral Hospital, the residence provides convenient accommodation for medical students undertaking clinical training and has remained an integral part of the university''s medical education infrastructure.',0.33880929999999998,32.5778747000000024,1924);
INSERT INTO landmarks (name, category, description, latitude, longitude, foundation_year) VALUES('College of Agricultural and Environmental Sciences (CAES)','College','Tracing its origins to the School of Agriculture established in 1922, the College of Agricultural and Environmental Sciences (CAES) is one of Makerere University''s oldest academic colleges. It has played a leading role in agricultural education, environmental management, food security, and scientific research in Uganda and across Africa. The college comprises modern teaching facilities, research laboratories, demonstration farms, and experimental gardens that support practical learning and innovation in agriculture and natural resource management.',0.3327663000000000148,32.56812709999999811,1922);
INSERT INTO landmarks (name, category, description, latitude, longitude, foundation_year) VALUES('University Oval (Main Sports Ground)','Infrastructure','Established in 1949, the University Oval is Makerere University''s principal sports ground and one of the campus''s most recognizable recreational landmarks. The facility hosts football, athletics, cricket, ceremonial events, inter-hall competitions, and university celebrations throughout the academic year. Surrounded by academic buildings and student residences, the Oval serves as a vibrant centre for sports, fitness, and community activities.',0.3293627000000000082,32.56563309999999945,1949);
INSERT INTO landmarks (name, category, description, latitude, longitude, foundation_year) VALUES('Lincoln Flats','Hall','Lincoln Flats are residential facilities within Makerere University that provide accommodation for members of the university community. The flats represent part of the institution''s continuous development of residential infrastructure to support students and campus residents. Located within the university environment, Lincoln Flats contribute to the wider residential landscape of Makerere by providing convenient accommodation close to academic facilities and other campus services.',0.3320420000000000038,32.56992890000000073,1960);
